export type IconProps = Omit<SVGProps<SVGSVGElement>, "ref"> & {
  size?: number | string;
  /** Draw the glyph filled rather than outlined. Only the glyphs themes/icons.json § filled lists
   *  have a filled form in every library. */
  filled?: boolean;
};

/** True asks every icon below it for its filled form, for a state a component marks by fill (a
 *  current nav item). Only the glyphs themes/icons.json § filled honour it; an explicit `filled`
 *  prop on the icon wins over it. */
export const IconFillContext = createContext(false);

// eslint-disable-next-line @typescript-eslint/no-explicit-any
function icon(Lib: ComponentType<any>, name: string, fillable = false, FilledLib?: ComponentType<any>) {
  const Icon = forwardRef<SVGSVGElement, IconProps>(({ className, size = "1em", filled: filledProp, ...props }, ref) => {
    const fromContext = useContext(IconFillContext);
    const filled = filledProp ?? (fillable && fromContext);
    return createElement(filled && FilledLib ? FilledLib : Lib, {
      ref,
      size,
      ...(filled ? { fill: "currentColor" } : {}),
      className: className ? `sd-icon ${className}` : "sd-icon",
      ...props,
    });
  });
  Icon.displayName = name;
  return Icon;
}

