/* GENERATED by scripts/build-icons.mjs from themes/icons.json. Do not edit; run `npm run icons:build`.
   The icon stroke follows the text beside it (docs/rules/icon-contract.md): each type-role class
   sets --sd-icon-stroke to its face's stem times that role's own font-size token (never 1em, which
   a unit may have reset to the icon size on the same element). The property is REGISTERED as a
   <length>, so it computes at the element carrying the class and descendants inherit the absolute
   length; unregistered, an em anywhere in it would resolve at the svg, which is the icon box. The shapes draw it with non-scaling-stroke, so the length is screen
   pixels whatever the icon's size or its viewBox. A CSS stroke-width outranks the SVG attribute the
   library writes. */
@property --sd-icon-stroke {
  syntax: "<length>";
  inherits: true;
  initial-value: 1.36px;
}

.sd-icon {
  stroke-width: var(--sd-icon-stroke);
}

/* vector-effect is not inherited, so it goes on every shape rather than on the svg. */
.sd-icon * {
  vector-effect: non-scaling-stroke;
}

